/// <summary>
/// MPJ_21713_MET PO receipts 
/// Event handler for <c>PurchFormLetter</c>
/// </summary>
class METPurchFormLetterEventHandler
{
}

Method.Source:
    /// <summary>
    /// PO Validate event handler
    /// </summary>
    /// <param name = "_args">args</param>
    [PostHandlerFor(classStr(PurchFormLetter), methodStr(PurchFormLetter, validate))]
    public static void validatePostHandler(XppPrePostArgs _args)
    {
        PurchFormLetter             purchFormLetter = _args.getThis();
        boolean                     ret;
        UnitOfMeasureSymbol         warehouseUnit;
        InventDim                   inventDim;
        Qty                         warehouseQty;
        METPurchLine                metPurchLine;
        PurchTable                  PurchTable = PurchFormLetter.purchTable();
        METPurchTable               metPurchTable;
        purchLine                   purchLine;
        boolean                     conversionFound;

        ret = _args.getReturnValue();

        DocumentStatus documentStatus = purchFormLetter.documentStatus();
        if (ret && (documentStatus == DocumentStatus::PurchaseOrder))
        {
            select firstonly RecId from metPurchLine
                join RecId from purchLine
                    where purchLine.RecId == metPurchLine.PurchLine
                exists join metPurchTable
                    where purchLine.PurchId == PurchTable.PurchId       &&
                          purchLine.PurchId == metPurchTable.PurchId    &&
                    ! purchLine.IsDeleted                               &&
                    purchLine.Blocked       == NoYes::No                &&
                    !metPurchLine.PromotionIHG                    &&
                    metPurchTable.POPromotionIHG;
                    
            if(metPurchLine.RecId)
            {
                ret = checkFailed("@MET:METPOPromotionValidation");
            }

            if(ret)
            {
                while select metPurchLine
                    join PurchUnit, ItemId, PurchQty, PurchId from purchLine
                        where purchLine.PurchId == PurchTable.PurchId
                           && purchLine.RecId == metPurchLine.PurchLine
                    join InventLocationId from inventDim
                        where inventDim.inventDimId == purchLine.InventDimId
                {
                
                    [conversionFound, warehouseQty, warehouseUnit] = METPurchFormLetterEventHandler::getWarehouseUnitAndQty(purchLine, inventDim.InventLocationId);
                    if(!conversionFound)
                    {
                        break;
                    }
                    else
                    {
                        ttsbegin;
                        metPurchLine.selectForUpdate(true);
                        metPurchLine.WarehouseUnitId = warehouseUnit;
                        metPurchLine.WarehouseQty = warehouseQty;
                        metPurchLine.doUpdate();
                        ttscommit;
                    }
                }
                if(!conversionFound)
                {
                    ret = ret && checkFailed(strFmt("@MET:POWarehouseUnitValidation", purchLine.ItemId));
                }
                
                if(ret && Global::isSystemAdministrator())
                {
                    PurchTable                      purchtableLoc;
                    METPurchTable                   METPurchTableLoc;
                    Valid                           isWarningPOBelowMinSetting;
                    AmountCur                       subTotalAmount = 0;
                    PurchTotals                     purchTotals;
                    SystemNotificationDataContract  notification;
                    QueryRun                        queryRunLoc = new QueryRun(purchFormLetter.parmQueryUsed());

                    while (queryRunLoc.next())
                    {
                        purchtableLoc   = queryRunLoc.get(tableNum(PurchTable));

                        METPurchTableLoc = METPurchTable::find(purchtableLoc.purchid);
                        isWarningPOBelowMinSetting = purchtableLoc.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup, WarningPOBelowMinSetting));

                        //Validation on PO minimum order value
                        // Initializing PurhTotals
                        purchTotals = PurchTotals::newPurchTable(purchtableLoc);
                        // Calculating values
                        purchTotals.calc();
 
                        // SubTotal Amount
                        subTotalAmount  = purchTotals.purchBalance();

                        if( isWarningPOBelowMinSetting == NoYes::Yes &&  subTotalAmount < METPurchTableLoc.POMinimumOrderValue )
                        {                        
                            // Set up the notification
                            notification = new SystemNotificationDataContract();
                            notification.Users().value(1, curUserId());
                            notification.Title(strFmt("@ProcurementAndSourcing:PurchStatusConsistencyCheck_PurchaseOrderLogSectionTitle", purchtableLoc.purchid));
                            notification.RuleId('POMinOrderValueWarning');
                            notification.Message(strFmt("@MET:POMinOrderValueWarning", purchtableLoc.purchid));
                            notification.Severity(SystemNotificationSeverity::Warning);
                            notification.ExpirationDateTime(DateTimeUtil::addHours(DateTimeUtil::utcNow(), 48));
                            SystemNotificationsManager::AddSystemNotification(notification);
                        }
                    }
                   
                }
            }
        }
        _args.setReturnValue(ret);
    }

    /// <summary>
    /// Method to determine if conversion exists  between the purchase and warehouse units
    /// </summary>
    /// <param name = "purchLine">the purchase line</param>
    /// <param name = "inventLocationId">the warehouse location</param>
    /// <returns>True if UOM conversion is found/else false and warehouse unit and the warehouse quantity</returns>
    public static container getWarehouseUnitAndQty(PurchLine purchLine, InventLocationId inventLocationId)
    {
        UnitOfMeasureConversion     unitOfMeasureConversion;
        boolean                     isUnitConversionPresent = true;
        UnitOfMeasureSymbol         purchUnit = purchLine.PurchUnit;
        ItemId                      itemId = purchLine.ItemId;
        Qty                         warehouseQty;
        InventTableModule           inventTableModule;
        UnitOfMeasureSymbol         inventoryUnit, warehouseUnit;
        PurchTable                  purchTable;
        InventLocationId            inventLocationIdLoc;
        InventLocation              inventLocation;
        METInventLocation           metInventLocation;
        METExtWMSUnit               externalWarehouseUnit;

        inventLocationIdLoc = inventLocationId;
        if(!inventLocationIdLoc)
        {
            select firstonly InventLocationId from purchTable
                where purchTable.PurchId == purchLine.PurchId;

            inventLocationIdLoc = purchTable.InventLocationId;
            if(!inventLocationIdLoc)
            {
                warehouseUnit = purchUnit;
                warehouseQty = purchLine.PurchQty;

                return [isUnitConversionPresent, warehouseQty, warehouseUnit];
            }
        }

        select firstonly ExternalWMSUnit from metInventLocation
            join RecId from inventLocation
                where metInventLocation.InventLocation == inventLocation.RecId
                    && inventLocation.InventLocationId == inventLocationIdLoc;

        externalWarehouseUnit = metInventLocation.ExternalWMSUnit;

        switch(externalWarehouseUnit)
        {
            case METExtWMSUnit::DefaultInventoryUnit : 
                select firstonly UnitId from inventTableModule
                    where inventTableModule.ItemId      == itemId
                        && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

                if(inventTableModule.UnitId)
                {

                    warehouseUnit = inventTableModule.UnitId;
                }
                break;

            case METExtWMSUnit::DefaultPurchaseUnit : 
                select firstonly UnitId from inventTableModule
                    where inventTableModule.ItemId      == itemId
                        && inventTableModule.ModuleType == ModuleInventPurchSales::Purch;

                if(inventTableModule.UnitId)
                {
                    warehouseUnit = inventTableModule.UnitId;
                }
                break;

            case METExtWMSUnit::DefaultSellUnit : 
                select firstonly UnitId from inventTableModule
                    where inventTableModule.ItemId      == itemId
                        && inventTableModule.ModuleType == ModuleInventPurchSales::Sales;

                if(inventTableModule.UnitId)
                {
                    warehouseUnit = inventTableModule.UnitId;
                }
                break;

            default  : warehouseUnit = purchUnit;
                       warehouseQty = purchLine.PurchQty;
                       return [isUnitConversionPresent, warehouseQty, warehouseUnit]; 
        }
             
        
        select firstonly UnitId from inventTableModule
            where inventTableModule.ItemId      == itemId
                && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

        if(inventTableModule.UnitId)
        {
            inventoryUnit = inventTableModule.UnitId;
        }

        if(purchUnit == warehouseUnit)
        {
            isUnitConversionPresent = true;
            warehouseQty = purchLine.PurchQty;
        }
        else if(warehouseUnit != METConstants::emptyString)
        {
            unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                            UnitOfMeasure::findBySymbol(purchUnit).RecId,
                            EcoResProduct::findByProductNumber(purchLine.ItemId).RecId);

            if(unitOfMeasureConversion.RecId)
            {
                isUnitConversionPresent = true;
                if(purchUnit == inventoryUnit)
                {
                    warehouseQty = purchLine.PurchQty / unitOfMeasureConversion.Factor;
                }
                else
                {
                    warehouseQty = purchLine.PurchQty * unitOfMeasureConversion.Factor;
                }
            }
            else
            {
                //Check purchase to warehouse conversion
                unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                            UnitOfMeasure::findBySymbol(purchUnit).RecId,
                            UnitOfMeasure::findBySymbol(warehouseUnit).RecId,
                            EcoResProduct::findByProductNumber(purchLine.ItemId).RecId);

                if(unitOfMeasureConversion.RecId)
                {
                    isUnitConversionPresent = true;
                    if(purchUnit == inventoryUnit)
                    {
                        warehouseQty = purchLine.PurchQty / unitOfMeasureConversion.Factor;
                    }
                    else
                    {
                        warehouseQty = purchLine.PurchQty * unitOfMeasureConversion.Factor;
                    }
                }
                else
                {
                    isUnitConversionPresent = false;
                }
            }
        }

        return [isUnitConversionPresent, warehouseQty, warehouseUnit];
    }
